4	export async function profilesRoutes(app: FastifyInstance): Promise<void> {
5	  // GET /api/profiles/:username - 프로필 조회
6	  app.get("/api/profiles/:username", async (request: FastifyRequest, reply: FastifyReply) => {
7	    const username = (request.params as any).username as string;
8	    const token = (request.headers as any).authorization as string | undefined;
9	    let currentUserId: string | null = null;
10	
11	    if (token) {
12	      try {
13	        const match = token.match(/^Token\s+(.+)$/i);
14	        if (match) {
15	          const jwt = await import("jsonwebtoken");
16	          const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
17	          const decoded = jwt.verify(match[1], JWT_SECRET) as any;
18	          currentUserId = decoded.id;
19	        }
20	      } catch {
21	        // ignore
22	      }
23	    }
24	
25	    const user = await prisma.user.findUnique({
26	      where: { username },
27	    });
28	
29	    if (!user) {
30	      return reply.code(404).send({ errors: { profile: ["not found"] } });
31	    }
32	
33	    let following = false;
34	    if (currentUserId && currentUserId !== user.id) {
35	      following = await prisma.follow.findUnique({
36	        where: {
37	          followerId_followingId: {
38	            followerId: currentUserId,
39	            followingId: user.id,
40	          },
41	        },
42	      }) !== null;
43	    }
44	
45	    return reply.send({
46	      profile: {
47	        username: user.username,
48	        bio: user.bio ?? null,
49	        image: user.image ?? null,
50	        following,
51	      },
52	    });
53	  });
54	
55	  // POST /api/profiles/:username/follow - 팔로우
56	  app.post("/api/profiles/:username/follow", async (request: FastifyRequest, reply: FastifyReply) => {
57	    const username = (request.params as any).username as string;
58	    const headers: any = request.headers;
59	    const authHeader = headers.authorization;
60	
61	    let token: string | null = null;
62	    if (authHeader) {
63	      const match = authHeader.match(/^Token\s+(.+)$/i);
64	      if (match) token = match[1];
65	    }
66	
67	    if (!token) {
68	      return reply.code(401).send({ errors: { token: ["is missing"] } });
69	    }
70	
71	    const jwt = await import("jsonwebtoken");
72	    const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
73	    let currentUserId: string;
74	    try {
75	      const decoded = jwt.verify(token, JWT_SECRET) as any;
76	      currentUserId = decoded.id;
77	    } catch {
78	      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
79	    }
80	
81	    const targetUser = await prisma.user.findUnique({
82	      where: { username },
83	    });
84	
85	    if (!targetUser) {
86	      return reply.code(404).send({ errors: { profile: ["not found"] } });
87	    }
88	
89	    if (currentUserId === targetUser.id) {
90	      return reply.code(409).send({ errors: { profile: ["can't follow yourself"] } });
91	    }
92	
93	    await prisma.follow.upsert({
94	      where: {
95	        followerId_followingId: {
96	          followerId: currentUserId,
97	          followingId: targetUser.id,
98	        },
99	      },
100	      create: {
101	        followerId: currentUserId,
102	        followingId: targetUser.id,
103	      },
