import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import prisma from "../lib/prisma.js";

export async function commentsRoutes(app: FastifyInstance): Promise<void> {
  // GET /api/articles/:slug/comments - 댓글 목록 조회
  app.get("/api/articles/:slug/comments", async (request: FastifyRequest, reply: FastifyReply) => {
    const slug = (request.params as any).slug as string;
    const token = (request.headers as any).authorization as string | undefined;
    let currentUserId: string | null = null;

    if (token) {
      try {
        const match = token.match(/^Token\s+(.+)$/i);
        if (match) {
          const jwt = await import("jsonwebtoken");
          const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
          const decoded = jwt.verify(match[1], JWT_SECRET) as any;
          currentUserId = decoded.id;
        }
      } catch {
        // ignore
      }
    }

    const article = await prisma.article.findUnique({
      where: { slug },
    });

    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    const comments = await prisma.comment.findMany({
      where: { articleId: article.id },
      include: {
        author: { select: { id: true, username: true, bio: true, image: true } },
      },
      orderBy: { createdAt: "desc" },
    });

    return reply.send({
      comments: comments.map((c) => ({
        id: c.id,
        body: c.body,
        createdAt: c.createdAt,
        updatedAt: c.updatedAt,
        author: {
          username: c.author.username,
          bio: c.author.bio ?? null,
          image: c.author.image ?? null,
        },
      })),
    });
  });

  // POST /api/articles/:slug/comments - 댓글 생성
  app.post("/api/articles/:slug/comments", async (request: FastifyRequest, reply: FastifyReply) => {
    const slug = (request.params as any).slug as string;
    const token = (request.headers as any).authorization as string | undefined;

    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    // 토큰 검증
    let currentUserId: string;
    try {
      const match = token.match(/^Token\s+(.+)$/i);
      if (!match) throw new Error("no match");
      const jwt = await import("jsonwebtoken");
      const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
      const decoded = jwt.verify(match[1], JWT_SECRET) as any;
      currentUserId = decoded.id;
    } catch {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }

    const { comment } = (request.body as any) as { comment?: { body?: string } };
    const { body } = comment || {};

    if (!body || body.trim() === "") {
      return reply.code(422).send({ errors: { body: ["can't be blank"] } });
    }

    const article = await prisma.article.findUnique({
      where: { slug },
    });

    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    const newComment = await prisma.comment.create({
      data: {
        body: body.trim(),
        articleId: article.id,
        authorId: currentUserId,
      },
      include: {
        author: { select: { id: true, username: true, bio: true, image: true } },
      },
    });

    return reply.code(201).send({
      comment: {
        id: newComment.id,
        body: newComment.body,
        createdAt: newComment.createdAt,
        updatedAt: newComment.updatedAt,
        author: {
          username: newComment.author.username,
          bio: newComment.author.bio ?? null,
          image: newComment.author.image ?? null,
        },
      },
    });
  });

  // DELETE /api/articles/:slug/comments/:id - 댓글 삭제
  app.delete("/api/articles/:slug/comments/:id", async (request: FastifyRequest, reply: FastifyReply) => {
    const slug = (request.params as any).slug as string;
    const commentId = parseInt((request.params as any).id as string, 10);
    const token = (request.headers as any).authorization as string | undefined;

    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    // 토큰 검증
    let currentUserId: string;
    try {
      const match = token.match(/^Token\s+(.+)$/i);
      if (!match) throw new Error("no match");
      const jwt = await import("jsonwebtoken");
      const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
      const decoded = jwt.verify(match[1], JWT_SECRET) as any;
      currentUserId = decoded.id;
    } catch {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }

    // 먼저 아티클 조회
    const article = await prisma.article.findUnique({
      where: { slug },
    });

    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    // 댓글 조회
    const comment = await prisma.comment.findUnique({
      where: { id: commentId },
    });

    if (!comment || comment.articleId !== article.id) {
      return reply.code(404).send({ errors: { comment: ["not found"] } });
    }

    // 작성자인지 확인
    if (comment.authorId !== currentUserId) {
      return reply.code(403).send({ errors: { comment: ["forbidden"] } });
    }

    await prisma.comment.delete({
      where: { id: commentId },
    });

    return reply.code(204).send();
  });
}

